head.script:
scwin.fireClick = function(node) {
    if (document.createEventObject || document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('click', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onclick == 'function') {
        node.onclick();
    }
}
scwin.click = function(cl) {
    var el = document.getElementsByClassName(cl)[0];
    scwin.fireClick(el);
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 27-Apr-2018
}
